import assert from "node:assert/strict";
import { createServer } from "node:https";
import { createReadStream, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { extname, join, resolve, sep } from "node:path";
import { tmpdir } from "node:os";
import { execFileSync } from "node:child_process";
import { chromium } from "playwright";

// CI exercises actual generated bytes over HTTPS with the production CSP.
const repo = process.cwd();
const output = resolve(".artifacts/menu-nutrition");
mkdirSync(output, { recursive: true });
const certificate = mkdtempSync(join(tmpdir(), "robys-nutrition-"));
execFileSync("openssl", ["req", "-x509", "-nodes", "-newkey", "rsa:2048", "-days", "1", "-keyout", join(certificate, "key.pem"),
  "-out", join(certificate, "cert.pem"), "-subj", "/CN=localhost"], { stdio: "ignore" });
const mime = { ".html": "text/html", ".js": "application/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml", ".webp": "image/webp", ".jpg": "image/jpeg" };
const server = createServer({ key: readFileSync(join(certificate, "key.pem")), cert: readFileSync(join(certificate, "cert.pem")) }, (request, response) => {
  try {
    const file = resolve(repo, "." + decodeURIComponent(new URL(request.url, "https://localhost").pathname));
    if (!file.startsWith(repo + sep)) return response.writeHead(403).end();
    if (!existsSync(file) || !statSync(file).isFile()) return response.writeHead(404).end();
    response.writeHead(200, { "content-type": mime[extname(file)] ?? "application/octet-stream", "cache-control": "no-store" });
    createReadStream(file).pipe(response);
  } catch { response.writeHead(400).end(); }
});
await new Promise(resolve => server.listen(0, "127.0.0.1", resolve));
const origin = `https://127.0.0.1:${server.address().port}`;
const cases = [
  { width: 320, height: 740, lang: "ru", view: "list", id: "hot-coffee:caffe-latte" },
  { width: 390, height: 844, lang: "en", view: "feed", id: "hot-coffee:caffe-latte" },
  { width: 1280, height: 900, lang: "tr", view: "list", id: "brew-hot:milk" },
  { width: 390, height: 844, lang: "ru", view: "list", id: "desserts:macaron" },
  { width: 390, height: 844, lang: "ru", view: "list", id: "pairing-offers:cool-lime-macaron-pairing",
    selection: "refreshers:cool-lime+desserts:macaron" },
  { width: 320, height: 740, lang: "ru", view: "feed", id: "cold-coffee:milkshake", variant: "strawberry" },
  { width: 740, height: 360, lang: "en", view: "list", id: "brew-hot:black-tea" }
];
const report = { head: execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim(),
  runtimes: Object.fromEntries(["menu-app.js", "menu-feed.js", "menu-order-ui.js", "menu-runtime.css"].map(file =>
    [file, createHash("sha256").update(readFileSync(file)).digest("hex")])), cases: [] };
let browser;
try {
  browser = await chromium.launch({ headless: true });
  for (const entry of cases) {
    const context = await browser.newContext({ viewport: { width: entry.width, height: entry.height },
      ignoreHTTPSErrors: true, serviceWorkers: "block", reducedMotion: "reduce" });
    const page = await context.newPage();
    const errors = [];
    page.on("pageerror", error => errors.push(error.message));
    try {
      const feed = entry.view === "feed";
      const query = new URLSearchParams({ view: entry.view, entry: "off", lang: entry.lang });
      if (feed) query.set("item", entry.id);
      await page.goto(`${origin}/${feed ? "menu-feed.html" : "menu.html"}?${query}`, { waitUntil: "domcontentloaded" });
      await page.locator(feed ? '#feed[data-ready="true"]' : '#menu-root[data-ready="true"]').waitFor();
      const card = page.locator(`[data-product-id="${entry.id}"]`).first();
      assert.match(await card.locator(feed ? ".menu-calories" : ".menu-nutrition-link").innerText(), /≈/);
      await card.locator(feed ? ".feed-details" : ".menu-nutrition-link").click();
      await page.locator("#menu-product-dialog[open]").waitFor();
      const panel = page.locator("#menu-product-nutrition");
      if (entry.selection) await page.waitForFunction(expected =>
        document.querySelector("#menu-product-nutrition")?.dataset.nutritionProduct === expected, entry.selection);
      assert.equal(await panel.getAttribute("data-nutrition-product"), entry.selection ?? entry.id);
      const summary = panel.locator("summary");
      await summary.focus();
      await summary.press("Enter");
      assert.equal(await panel.locator("details").getAttribute("open"), "");
      assert.equal(await panel.locator("dd").count(), 3);
      if (entry.variant) {
        await page.locator("#menu-product-variant").selectOption(entry.variant);
        assert.equal(await panel.locator("details").getAttribute("open"), "");
        assert.match(await panel.locator("dd").first().innerText(), /Клубника/);
      }
      if (entry.id === "desserts:macaron") assert.match(await panel.innerText(), /20 г/);
      if (entry.selection) {
        assert.match(await panel.innerText(), /150–290/);
        assert.match(await panel.innerText(), /350 мл \+ 20 г/);
      }
      const geometry = await panel.evaluate(element => {
        const dialog = element.closest("dialog");
        return { pageWidth: document.documentElement.clientWidth, pageScroll: document.documentElement.scrollWidth,
          dialogWidth: dialog.clientWidth, dialogScroll: dialog.scrollWidth, panelWidth: element.clientWidth, panelScroll: element.scrollWidth };
      });
      assert.ok(geometry.pageScroll <= geometry.pageWidth + 1, "no horizontal page overflow");
      assert.ok(geometry.dialogScroll <= geometry.dialogWidth + 1, "no horizontal dialog overflow");
      assert.ok(geometry.panelScroll <= geometry.panelWidth + 1, "nutrition text reflows");
      const screenshot = `${entry.width}x${entry.height}-${entry.lang}-${entry.view}-${entry.id.split(":")[1]}.png`;
      await page.screenshot({ path: join(output, screenshot) });
      if (entry.width <= 390) {
        await panel.locator("dd").last().scrollIntoViewIfNeeded();
        await page.screenshot({ path: join(output, `vitamins-${screenshot}`) });
      }
      const add = page.locator("#menu-add-to-cart");
      await add.scrollIntoViewIfNeeded();
      const bounds = await add.boundingBox();
      assert.ok(bounds.y >= 0 && bounds.y + bounds.height <= entry.height + 1, "order action remains reachable");
      await add.click();
      await page.locator("#menu-cart-dialog[open]").waitFor();
      assert.deepEqual(errors, [], "product details and ordering must not produce runtime errors");
      report.cases.push({ ...entry, status: "PASS", geometry, screenshot });
    } catch (error) {
      report.cases.push({ ...entry, status: "FAIL", error: String(error), pageErrors: errors });
      await page.screenshot({ path: join(output, `failure-${entry.width}-${entry.lang}-${entry.view}.png`) }).catch(() => {});
      throw error;
    } finally { await context.close(); }
  }
} finally {
  writeFileSync(join(output, "report.json"), JSON.stringify(report, null, 2));
  await browser?.close();
  await new Promise(resolve => server.close(resolve));
  rmSync(certificate, { recursive: true, force: true });
}
console.log(`Nutrition browser PASS: ${report.cases.length} responsive, multilingual list/feed cases with ordering.`);
